  "confidence": "high",
  "uncertainties": [],
  "risk": {
    "level": "medium",
    "touches": [
      "build"
    ],
    "why": "Raising minimum compiler versions will break build environments for packagers and developers running older distributions without GCC 13 or Clang 19."
  }
}
